<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">shared_preload_libraries</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pgaudit&#39;</span></span>
